using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class TempEvansFinalInspect{static TempEvansFinalInspect(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;EditorApplication.update-=Run;if(File.Exists("Temp/EvansFinalInspect.done"))return;var s=SceneManager.GetSceneByPath("Assets/_Project/Locations/Hangar.unity");var txt="";foreach(var t in s.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).Where(x=>x.name.StartsWith("Hangar Truck")||x.name.Contains("манекен Бена"))){txt+=t.name+" pos="+t.position+" rot="+t.eulerAngles+" scale="+t.lossyScale+"\n";var b=new Bounds();bool first=true;foreach(var r in t.GetComponentsInChildren<Renderer>()){if(first){b=r.bounds;first=false;}else b.Encapsulate(r.bounds);}txt+="bounds "+b+"\n";}File.WriteAllText("Temp/EvansFinalInspect.done",txt);}}